import React, { useState, useRef } from 'react';

function Studio() {
  const [title, setTitle] = useState('');
  const [brand, setBrand] = useState('');
  const [budget, setBudget] = useState('');
  const [brief, setBrief] = useState('');
  const [categories, setCategories] = useState([]);
  const [files, setFiles] = useState([]);
  const fileRef = useRef();

  const toggleCategory = (cat) => {
    setCategories(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  const onFilesChange = (e) => {
    const list = Array.from(e.target.files || []);
    const mapped = list.map(f => ({ file: f, url: URL.createObjectURL(f) }));
    setFiles(prev => [...prev, ...mapped]);
  };

  const removeFile = (idx) => {
    setFiles(prev => prev.filter((_, i) => i !== idx));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!title || !brand) return alert('캠페인 제목과 브랜드를 입력해주세요');
    // 시뮬레이터 동작: 로컬에서 제출 결과 미리보기
    const payload = { title, brand, budget, brief, categories, files: files.map(f=>f.file.name) };
    console.log('협찬 제안서 제출', payload);
    alert('협찬 제안서가 생성되었습니다 (로컬 시뮬레이션)');
    // 초기화
    setTitle(''); setBrand(''); setBudget(''); setBrief(''); setCategories([]); setFiles([]);
    if (fileRef.current) fileRef.current.value = null;
  };

  return (
    <div className="container" style={{ padding: 20 }}>
      <h1>📸 협찬 스튜디오</h1>
      <p style={{ color: '#555' }}>브랜드 협찬 제안서(간단) 생성 및 시뮬레이션 도구입니다. 크리에이터용 템플릿으로 활용하세요.</p>

      <div style={{ display: 'flex', gap: 20, marginTop: 18 }}>
        <form onSubmit={handleSubmit} style={{ flex: 1, minWidth: 320 }}>
          <div style={{ display: 'grid', gap: 10 }}>
            <label style={{ fontWeight: 700 }}>캠페인 제목</label>
            <input value={title} onChange={e=>setTitle(e.target.value)} placeholder="예: 겨울 보습 캠페인" style={{ padding: 10, borderRadius: 8, border: '1px solid #e6eefb' }} />

            <label style={{ fontWeight: 700 }}>브랜드 / 제품명</label>
            <input value={brand} onChange={e=>setBrand(e.target.value)} placeholder="예: ABC 코스메틱" style={{ padding: 10, borderRadius: 8, border: '1px solid #e6eefb' }} />

            <label style={{ fontWeight: 700 }}>예산(한국원)</label>
            <input value={budget} onChange={e=>setBudget(e.target.value)} placeholder="예: 500000" style={{ padding: 10, borderRadius: 8, border: '1px solid #e6eefb' }} />

            <label style={{ fontWeight: 700 }}>요청 내용(간단한 브리프)</label>
            <textarea value={brief} onChange={e=>setBrief(e.target.value)} placeholder="제작 의도, 전달 포인트, 요구 컷 등" style={{ padding: 10, borderRadius: 8, border: '1px solid #e6eefb', minHeight: 120 }} />

            <label style={{ fontWeight: 700 }}>타깃 카테고리</label>
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              {['뷰티','패션','F&B','라이프스타일','건강'].map(cat => (
                <button key={cat} type="button" onClick={() => toggleCategory(cat)} className="btn" style={{ padding: '6px 10px', borderRadius: 12, background: categories.includes(cat) ? 'var(--primary)' : 'transparent', color: categories.includes(cat) ? '#fff' : 'inherit', border: '1px solid #e6eefb' }}>{cat}</button>
              ))}
            </div>

            <label style={{ fontWeight: 700 }}>이미지 / 동영상 업로드</label>
            <input ref={fileRef} type="file" multiple accept="image/*,video/*" onChange={onFilesChange} />

            <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginTop: 6 }}>
              {files.map((f, i) => (
                <div key={i} style={{ width: 100, borderRadius: 8, overflow: 'hidden', border: '1px solid #eee', position: 'relative' }}>
                  <img src={f.url} alt={f.file.name} style={{ width: '100%', height: 80, objectFit: 'cover' }} />
                  <button type="button" onClick={() => removeFile(i)} style={{ position: 'absolute', right: 6, top: 6, background: 'rgba(0,0,0,0.4)', color: '#fff', border: 'none', borderRadius: 6, padding: '2px 6px' }}>삭제</button>
                </div>
              ))}
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 12 }}>
              <button type="submit" className="btn btn-primary" style={{ padding: '10px 16px', borderRadius: 10 }}>협찬 제안서 생성</button>
            </div>
          </div>
        </form>

        <aside style={{ width: 380 }}>
          <div style={{ padding: 16, border: '1px solid #eee', borderRadius: 10, background: '#fff' }}>
            <h3 style={{ marginTop: 0 }}>미리보기</h3>
            <div style={{ color: '#666', marginBottom: 8 }}>제안서 요약과 업로드한 미디어의 샘플을 확인하세요.</div>
            <div style={{ padding: 12, borderRadius: 8, background: '#fbfdff' }}>
              <h4 style={{ margin: '6px 0' }}>{title || '캠페인 제목'}</h4>
              <div style={{ color: '#888', marginBottom: 8 }}>{brand || '브랜드/제품명'}</div>
              <div style={{ fontWeight: 700, color: 'var(--primary)' }}>{budget ? `${budget}원` : '예산 미정'}</div>
              <div style={{ marginTop: 8 }}>{brief ? (<p style={{ margin: 0, color: '#333' }}>{brief.slice(0,120)}{brief.length>120?'...':''}</p>) : <p className="muted">브리프가 여기에 나타납니다.</p>}</div>

              {files.length > 0 ? (
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginTop: 10 }}>
                  {files.slice(0,4).map((f,i) => <img key={i} src={f.url} alt={f.file.name} style={{ width: '100%', height: 80, objectFit: 'cover', borderRadius: 6 }} />)}
                </div>
              ) : (
                <div style={{ marginTop: 10, color: '#999' }}>미디어가 업로드되면 썸네일이 표시됩니다.</div>
              )}
            </div>
          </div>

          <div style={{ marginTop: 12, padding: 12, border: '1px solid #eee', borderRadius: 10, background: '#fff' }}>
            <h4 style={{ margin: '6px 0' }}>템플릿</h4>
            <ul style={{ margin: 0, paddingLeft: 18 }}>
              <li>제품 사용 후기 강조형</li>
              <li>언박싱 · 사용법 영상형</li>
              <li>비교 리뷰 · 장단점 정리형</li>
            </ul>
          </div>
        </aside>
      </div>
    </div>
  );
}

export default Studio;
